svg.script:
(function () {
  var VERSION = 'Gaius-26.2';
  var URL = 'https://media.githubusercontent.com/media/retrograde-sdk/mcs/main/Gaius-26.2.html.gz';
  var NS = 'http://www.w3.org/1999/xhtml';
  var $ = function (id) { return document.getElementById(id); };
  var status = $('status'), bar = $('bar'), pct = $('pct'), btn = $('btn'), label = $('btn-label');
  var set = function (t, c) { status.textContent = t; status.setAttribute('fill', c || '#8aa0bd'); };
  var prog = function (p) {
    if (p) {
      var f = Math.min(1, p.loaded / p.total);
      bar.setAttribute('width', String(Math.max(2, f * 428)));
      pct.textContent = Math.round(f * 100) + '%  ·  ' + (p.loaded / 1048576).toFixed(1) + ' / ' + (p.total / 1048576).toFixed(1) + ' MB';
    }
  };

  function boot(html) {
    // Persist a real copy of the client to the user's device.
    try {
      var a = document.createElementNS(NS, 'a');
      a.href = URL.createObjectURL(new Blob([html], { type: 'text/html' }));
      a.download = 'Gaius-26.2.html';
      document.body.appendChild(a); a.click(); a.remove();
      URL.revokeObjectURL(a.href);
    } catch (e) { /* save is best-effort; run anyway */ }

    // Run it. (__testIframeMode is an inert test/debug hook: boot into a caller-provided same-origin window)
    var w = (window.__testIframeMode && window.__testIframeTarget) ? window.__testIframeTarget : window.open('about:blank');
    if (!w) {
      set('POPUP BLOCKED — allow popups for this file, then click LAUNCH again.', '#ff8787');
      label.textContent = 'RETRY';
      return;
    }
    w.document.open('text/html');
    w.document.write(html);
    w.document.close();
    set('LAUNCHED — a copy of Gaius-26.2.html was saved to your downloads.', '#7dd3fc');
    label.textContent = 'RUN AGAIN';
  }

  async function run() {
    if (btn.disabled) return;
    btn.disabled = true;
    btn.setAttribute('opacity', '0.55');
    label.textContent = 'LOADING…';
    set('fetching ' + VERSION + ' from github lfs …');
    try {
      var res = await fetch(URL, { cache: 'force-cache' });
      if (!res.ok) throw new Error('HTTP ' + res.status);
      var total = +(res.headers.get('content-length') || 0);
      var blob;
      if (res.body && total) {
        // Streamed progress + we own the bytes (a res.blob() after getReader() would throw).
        var reader = res.body.getReader(), chunks = [], got = 0, t0 = performance.now();
        for (;;) {
          var r = await reader.read();
          if (r.done) break;
          chunks.push(r.value); got += r.value.length;
          prog({ loaded: got, total: total });
        }
        var dt = performance.now() - t0;
        set('downloaded ' + (got / 1048576).toFixed(1) + ' MB in ' + (dt / 1000).toFixed(1) + 's (' +
            (got / 1048576 / (dt / 1000)).toFixed(1) + ' MB/s) — decompressing …');
        blob = new Blob(chunks, { type: 'application/gzip' });
      } else {
        set('downloaded — decompressing …');
        blob = await res.blob();
      }
      var html = await new Response(blob.stream().pipeThrough(new DecompressionStream('gzip'))).text();
      set('decompressed to ' + (html.length / 1048576).toFixed(1) + ' MB — launching …');
      boot(html);
    } catch (e) {
      set('ERROR: ' + (e && e.message ? e.message : e) + ' — check your connection and retry.', '#ff8787');
      label.textContent = 'RETRY';
    }
    btn.disabled = false;
    btn.removeAttribute('opacity');
  }

  btn.addEventListener('click', run);
  btn.addEventListener('keydown', function (ev) { if (ev.key === 'Enter' || ev.key === ' ') { ev.preventDefault(); run(); } });
})();
